L["|cffff8080not armed for now:|r %s."] = "|cffff8080non armé pour l'instant :|r %s."
L["expands to: |cffffffff%s|r"] = "donne : |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d caractères -- %d de plus que les %d que peut contenir une macro. Le client la coupera, et ce qui s'exécute n'est pas ce qui est affiché ci-dessus."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Cela prendra effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton. |cffffd100/manners try|r sans argument l'efface."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Le panneau l'armera dès qu'il en aura un. |cffffd100/manners try|r sans argument l'efface."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Cliquez sur le panneau pour l'exécuter. |cffffd100/manners try|r sans argument l'efface."
L["Targeting forms, for /manners try:"] = "Formes de ciblage, pour /manners try :"
L["(on yourself)"] = "(sur vous-même)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Balises : |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} est le nom sous lequel une dette est enregistrée, {aim} est ce qu'attend une ligne de ciblage. Utilisez \\n pour un retour à la ligne."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "le registre des faveurs ne s'est pas chargé -- réinstaller Manners devrait le rétablir."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "déverrouillé -- vous pourrez le déplacer à la fin de ce combat ; d'ici là, un appui lance toujours ce que le combat a figé. Ensuite, |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "déverrouillé -- déplacez le panneau, puis |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "déverrouillé, mais l'addon est |cffff8080désactivé|r, donc il n'y a aucun panneau à déplacer -- d'abord |cffffd100/manners on|r."
L["locked."] = "verrouillé."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "rétablissement de votre cible après avoir buffé : |cff00ff00activé|r -- prend effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "rétablissement de votre cible après avoir buffé : |cffff0000désactivé|r -- prend effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton."
L["hand your target back after buffing: |cff00ff00on|r"] = "rétablissement de votre cible après avoir buffé : |cff00ff00activé|r"
L["hand your target back after buffing: |cffff0000off|r"] = "rétablissement de votre cible après avoir buffé : |cffff0000désactivé|r"
L["click logging: |cff00ff00on|r"] = "journal des clics : |cff00ff00activé|r"
L["click logging: |cffff0000off|r"] = "journal des clics : |cffff0000désactivé|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "mode détaillé : |cff00ff00activé|r -- une ligne dans votre propre fenêtre de discussion quand quelqu'un vous buffe, quand une faveur est comptée comme rendue, et quand un clic échoue, est passé ou laisse une faveur encore due"
L["verbose: |cffff0000off|r"] = "mode détaillé : |cffff0000désactivé|r"
L["enabled."] = "activé."
L["disabled."] = "désactivé."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "personne n'est sur votre liste d'exclusion. Faites un Maj-clic droit sur le panneau pour y ajouter le joueur affiché."
L["never offered anything unless they buff you: %s"] = "rien ne leur est proposé, sauf s'ils vous buffent : %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "précisez qui : |cffffd100/manners allow Name|r. |cffffd100/manners never|r affiche toute la liste."
