L["the prompt stays away while you are mounted -- get off, or switch off %s on the %s tab."] = "le panneau reste masqué quand vous êtes sur une monture -- descendez de monture, ou désactivez %s dans l'onglet %s."
L["Not while mounted"] = "Pas sur une monture"
L["When"] = "Quand"
L["nothing learned to cast yet."] = "vous n'avez encore appris aucun sort à lancer."
L["nobody to buff right now."] = "personne à buffer pour l'instant."
L["|cffff8080that may still have cast|r -- the prompt cannot be disarmed in combat, and nothing was recorded for it."] = "|cffff8080cet appui a peut-être quand même lancé un sort|r -- le panneau ne peut pas être désarmé en combat, et rien n'a été enregistré à ce sujet."
L["nobody to skip right now."] = "personne à passer pour l'instant."
L["skipping |cffffffff%s|r for now."] = "|cffffffff%s|r passé pour l'instant."
L["held back -- the cooldown was still running"] = "retenu -- le temps de recharge n'était pas terminé"
L["Buffed you -- return the favour."] = "Vous a buffé -- rendez-lui la politesse."
L["In your group, and theirs is running out."] = "Dans votre groupe, et son amélioration s'épuise."
L["Your target, and theirs is running out."] = "Votre cible, et son amélioration s'épuise."
L["Nearby, and theirs is running out."] = "À proximité, et son amélioration s'épuise."
L["In your group and missing it."] = "Dans votre groupe, et il ne l'a pas."
L["Your target, and missing it."] = "Votre cible, et il ne l'a pas."
L["Nearby and missing it."] = "À proximité, et il ne l'a pas."
L["In your group."] = "Dans votre groupe."
L["Your target."] = "Votre cible."
L["Nearby."] = "À proximité."
L["On your friends list."] = "Dans votre liste d'amis."
L["In your guild."] = "Dans votre guilde."
L["Theirs expires in %s."] = "Son amélioration expire dans %s."
L["Buff state unreadable on this build -- they may already have it."] = "État des améliorations illisible sur cette version -- il l'a peut-être déjà."
L["Not checking whether they have it -- set by your options."] = "Sans vérifier s'il l'a déjà -- selon vos options."
L["Will run:"] = "Exécutera :"
L["Click to cast. %s for options."] = "Cliquez pour lancer le sort. %s pour les options."
L["Right-click to skip this one."] = "Clic droit pour passer celui-ci."
L["Shift-right-click to let this favour go."] = "Maj-clic droit pour abandonner cette faveur."
L["Shift-right-click to put them on your never-offer list."] = "Maj-clic droit pour l'ajouter à votre liste d'exclusion."
L["|cffffcc66Does nothing:|r %s."] = "|cffffcc66Ne fait rien :|r %s."
L["Runs your |cffffd100/manners try|r macro against |cffffffff%s|r."] = "Exécute votre macro |cffffd100/manners try|r sur |cffffffff%s|r."
L["Runs your |cffffd100/manners try|r macro against |cffffffffthem|r."] = "Exécute votre macro |cffffd100/manners try|r sur |cffffffffce joueur|r."
L["Casts |cffffffff%s|r on you; it reaches your party from there."] = "Lance |cffffffff%s|r sur vous ; le sort atteint ensuite votre groupe."
L["Targets |cffffffff%s|r, casts |cffffffff%s|r."] = "Cible |cffffffff%s|r, puis lance |cffffffff%s|r."
L["Targets |cffffffffthem|r, casts |cffffffff%s|r."] = "Cible |cffffffffce joueur|r, puis lance |cffffffff%s|r."
L["Hands your own target back afterwards."] = "Rétablit ensuite votre cible d'origine."
L["They are already your target, so they stay targeted."] = "C'est déjà votre cible, il reste donc ciblé."
L["|cffffcc66Leaves them targeted|r -- your own target is not restored."] = "|cffffcc66Le laisse ciblé|r -- votre cible d'origine n'est pas rétablie."
L["Says: |cffffffff%s|r"] = "Dit : |cffffffff%s|r"
L["PREVIEW"] = "APERÇU"
L["preview off."] = "aperçu désactivé."
L["|cffff8080not during a fight|r -- the preview can be shown once it ends."] = "|cffff8080pas pendant un combat|r -- l'aperçu pourra être affiché une fois le combat terminé."
L["somebody real is on the prompt, so there is nothing to preview -- open |cffffd100/manners|r to style it; a preview holds while that window is open."] = "un vrai joueur est sur le panneau, il n'y a donc rien à prévisualiser -- ouvrez |cffffd100/manners|r pour le personnaliser ; l'aperçu reste affiché tant que cette fenêtre est ouverte."
L["preview on -- it stays while the options window is open, then %ds longer, or |cffffd100/manners test|r to stop."] = "aperçu activé -- il reste tant que la fenêtre des options est ouverte, puis %d s de plus, ou |cffffd100/manners test|r pour l'arrêter."
L["the prompt has moved on to |cffffffff%s|r -- press again to buff them."] = "le panneau est passé à |cffffffff%s|r -- appuyez de nouveau pour le buffer."
L["|cffff8080could not buff|r |cffffffff%s|r"] = "|cffff8080impossible de buffer|r |cffffffff%s|r"
L["|cffff8080could not buff|r |cffffffffthem|r"] = "|cffff8080impossible de buffer|r |cffffffffce joueur|r"
L["|cffe8e0a0sent to|r |cffffffff%s|r"] = "|cffe8e0a0envoyé à|r |cffffffff%s|r"
L["|cffe8e0a0sent to|r |cffffffffthem|r"] = "|cffe8e0a0envoyé à|r |cffffffffce joueur|r"
L["|cff8ce88cbuffed|r |cffffffff%s|r"] = "|cff8ce88cbuffé :|r |cffffffff%s|r"
L["|cff8ce88cbuffed|r |cffffffffthem|r"] = "|cff8ce88cbuffé :|r |cffffffffce joueur|r"
L["the game confirmed it"] = "le jeu l'a confirmé"
L["still armed by the fight"] = "armé et figé par le combat"
L["nothing to buff"] = "personne à buffer"
L["nothing this character can cast -- a press still casts what the fight froze"] = "rien à lancer pour ce personnage -- un appui lance toujours ce que le combat a figé"
L["nothing this character can cast -- nothing armed, and the panel cannot go"] = "rien à lancer pour ce personnage -- rien d'armé, et le panneau ne peut pas disparaître"
L["preview off -- timed out."] = "aperçu désactivé -- délai écoulé."
L["preview off -- somebody real turned up."] = "aperçu désactivé -- un vrai joueur est arrivé."
L["Someone %d"] = "Joueur %d"
L["switched off -- a press still casts what the fight froze"] = "désactivé -- un appui lance toujours ce que le combat a figé"
L["switched off -- nothing armed, and the panel cannot go"] = "désactivé -- rien d'armé, et le panneau ne peut pas disparaître"
L["Drag to move"] = "Glisser pour déplacer"
L["not buffing while unlocked"] = "inactif tant que déverrouillé"
L["unlocked -- a press still casts what the fight froze"] = "déverrouillé -- un appui lance toujours ce que le combat a figé"
L["unlocked -- nothing armed, and the panel cannot go"] = "déverrouillé -- rien d'armé, et le panneau ne peut pas disparaître"
L["held -- in combat"] = "figé -- en combat"
L["held -- a press still casts what the fight froze"] = "figé -- un appui lance toujours ce que le combat a figé"
L["held -- nothing armed, and the panel cannot go"] = "figé -- rien d'armé, et le panneau ne peut pas disparaître"
L["ready in %.1fs"] = "prêt dans %.1f s"
L["%s |cffffd100snoozed until %s|r"] = "%s |cffffd100en pause jusqu'à %s|r"
L["%s |cffff8080off|r"] = "%s |cffff8080désactivé|r"
L["%s |cff80e0801 waiting|r"] = "%s |cff80e0801 en attente|r"
L["%s |cff80e080%d waiting|r"] = "%s |cff80e080%d en attente|r"
L["Automatic"] = "Automatique"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(non appris)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(classes à mana uniquement)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(votre groupe uniquement)|r"
L["This character has nothing it can cast on another player."] = "Ce personnage n'a rien à lancer sur un autre joueur."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Vous n'avez encore appris aucun de ces sorts, donc rien ne sera proposé à personne."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "Le mode Automatique ne propose jamais le sort %s -- personne n'en a besoin en ville -- donc rien ne sera proposé à personne."
L["Pin it in the dropdown above if you want it given out anyway."] = "Épinglez-le dans le menu déroulant ci-dessus si vous voulez quand même le distribuer."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Tous les sorts que vous avez appris sont désactivés, donc rien n'est proposé tant que vous n'en réactivez pas un ou n'apprenez pas l'un des autres."
L["Every spell below is switched off, so the prompt will never appear."] = "Tous les sorts ci-dessous sont désactivés, donc le panneau n'apparaîtra jamais."
L["Your blessings replace one another, so Automatic gives one and stops: the first of %s that suits them. Anybody already carrying one of yours is left alone rather than handed a different one -- except with |cffffd100Always offer|r chosen, which does not look: then the first that suits them is offered, and it can replace one of yours."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique en donne une et s'arrête : la première parmi %s qui convient au joueur. Quiconque porte déjà l'une des vôtres est laissé tranquille plutôt que d'en recevoir une autre -- sauf si |cffffd100Toujours proposer|r est choisi, car ce réglage ne vérifie rien : la première qui lui convient est alors proposée, et elle peut remplacer l'une des vôtres."
L["Your blessings replace one another, so Automatic gives one and stops: the first of %s that suits them. Anybody already carrying one of yours is left alone rather than handed a different one -- except where the game won't show which blessing they carry: then the first that suits them is offered, and it can replace one of yours."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique en donne une et s'arrête : la première parmi %s qui convient au joueur. Quiconque porte déjà l'une des vôtres est laissé tranquille plutôt que d'en recevoir une autre -- sauf quand le jeu ne montre pas quelle bénédiction il porte : la première qui lui convient est alors proposée, et elle peut remplacer l'une des vôtres."
L["Your blessings replace one another, so Automatic gives one and stops: the first of %s that suits them. Anybody already carrying one of yours is left alone rather than handed a different one."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique en donne une et s'arrête : la première parmi %s qui convient au joueur. Quiconque porte déjà l'une des vôtres est laissé tranquille plutôt que d'en recevoir une autre."
L["Automatic offers the first of these they are missing, in this order: %s."] = "Le mode Automatique propose le premier de ces sorts qui manque au joueur, dans cet ordre : %s."
L["Where the game will not say what somebody is carrying, it moves down the list each time instead of offering the same one over and over."] = "Quand le jeu ne dit pas ce que porte un joueur, le mode Automatique descend la liste à chaque fois au lieu de proposer sans cesse le même sort."
L["Only |cffffffff%s|r is ever offered, to everybody, whatever else they are missing. The per-spell switches above apply to Automatic and are left alone while one spell is pinned."] = "Seul le sort |cffffffff%s|r sera proposé, à tout le monde, quoi qu'il leur manque d'autre. Les options par sort ci-dessus s'appliquent au mode Automatique et restent inchangées tant qu'un sort est épinglé."
L["You have pinned %s, which you have not learned."] = "Vous avez épinglé le sort %s, que vous n'avez pas appris."
L["Nothing will be offered to anybody until you learn it or switch back to Automatic -- a pinned spell is the only one considered, so there is nothing to fall back to."] = "Rien ne sera proposé à personne tant que vous ne l'aurez pas appris ou que vous ne serez pas revenu au mode Automatique -- un sort épinglé est le seul pris en compte, il n'y a donc rien sur quoi se rabattre."
L["Switched off, this one is never offered to anybody and Automatic walks straight past it. Everything else carries on as before."] = "Une fois désactivé, ce sort n'est jamais proposé à personne et le mode Automatique le saute. Tout le reste continue comme avant."
L["Who to buff"] = "Qui buffer"
L["Buffs"] = "Améliorations"
L["Buff to cast"] = "Amélioration à lancer"
L["Sources"] = "Sources"
L["Nothing below is switched on, so the prompt will never appear."] = "Rien n'est activé ci-dessous, donc le panneau n'apparaîtra jamais."
L["People who buffed me"] = "Ceux qui m'ont buffé"
L["Watch for buffs cast on you and offer to return them. What you cast reaches only your own party -- in a raid, your own subgroup -- so somebody outside it is offered once they join."] = "Surveille les améliorations lancées sur vous et propose de rendre la politesse. Vos sorts n'atteignent que votre propre groupe -- en raid, votre sous-groupe -- donc quelqu'un d'extérieur n'est proposé qu'une fois qu'il l'a rejoint."
L["Watch for buffs cast on you and offer to return them. What you cast reaches your group only, so somebody outside it is offered once they join."] = "Surveille les améliorations lancées sur vous et propose de rendre la politesse. Vos sorts n'atteignent que votre groupe, donc quelqu'un d'extérieur n'est proposé qu'une fois qu'il l'a rejoint."
L["Watch for buffs cast on you and offer to return them. Works on strangers who are not in your group."] = "Surveille les améliorations lancées sur vous et propose de rendre la politesse. Fonctionne aussi avec les inconnus hors de votre groupe."
L["Only count real class buffs"] = "Ne compter que les vraies améliorations de classe"
L["A shield, a heal-over-time or a trinket proc is not a favour owed. Leave this on unless you want every incoming aura to count."] = "Un bouclier, un soin sur la durée ou un déclenchement de bijou n'est pas une faveur due. Laissez cette option activée sauf si vous voulez que chaque aura reçue compte."
L["My party and raid"] = "Mon groupe et mon raid"
L["Nearby players not in my group"] = "Joueurs proches hors de mon groupe"
L["Offer passers-by who are missing the buff. Seen through nameplates, your target, your focus and your mouseover."] = "Propose les passants à qui il manque l'amélioration. Repérés via les barres d'info, votre cible, votre focalisation et l'unité sous votre curseur."
L["Everything you can offer is cast on yourself and heard by your party, so there is nothing to give a passer-by."] = "Tout ce que vous pouvez proposer se lance sur vous et est entendu par votre groupe, donc il n'y a rien à donner à un passant."
L["Who comes first"] = "Qui passe en premier"
L["Whoever I have targeted comes first"] = "Ma cible passe en premier"
L["Targeting somebody is the plainest way of saying you mean them, so they outrank a favour owed -- but only when the game lets us read that they are genuinely missing the buff. Switched off, a target is ranked by why they are on the list like anybody else."] = "Cibler quelqu'un est la façon la plus simple de dire que c'est lui que vous voulez, donc il passe avant une faveur due -- mais seulement quand le jeu nous permet de vérifier qu'il lui manque vraiment l'amélioration. Si l'option est désactivée, votre cible est classée selon la raison de sa présence dans la liste, comme n'importe qui."
L["Not while |cffffd100If they already have the buff|r is set to Always offer, under When: nothing is read then, so your target is ranked by why they are on the list like anybody else."] = "Pas quand |cffffd100S'il a déjà l'amélioration|r est réglé sur « Toujours proposer », dans l'onglet Quand : rien n'est alors lu, donc votre cible est classée selon la raison de sa présence dans la liste, comme n'importe qui."
L["Mouseover is deliberately left out: at a scan every four tenths of a second the prompt would flicker as the cursor crossed the screen."] = "L'unité sous votre curseur est volontairement exclue : avec une analyse tous les quatre dixièmes de seconde, le panneau clignoterait au gré des déplacements du curseur à l'écran."
L["My friends and guildmates come before the others"] = "Mes amis et ma guilde passent avant les autres"
L["A friend or guildmate passing by comes ahead of the other passers-by, and one in your group ahead of the rest of your group. People who buffed you still come first, and so does your target whenever |cffffd100Whoever I have targeted comes first|r puts them there. Nobody is added or left out by this -- it only changes the order."] = "Un ami ou un membre de votre guilde qui passe par là devance les autres passants, et s'il est dans votre groupe, il devance le reste de votre groupe. Ceux qui vous ont buffé passent toujours en premier, tout comme votre cible chaque fois que |cffffd100Ma cible passe en premier|r la place là. Cette option n'ajoute ni n'exclut personne -- elle ne change que l'ordre."
L["Friends include Battle.net friends. When the game will not say whether somebody is a friend, they are ranked like anybody else."] = "Les amis comprennent les amis Battle.net. Quand le jeu ne dit pas si quelqu'un est un ami, il est classé comme n'importe qui."
L["Who to skip"] = "Qui ignorer"
L["Mana-only buffs such as Arcane Intellect, Wisdom and Divine Spirit are wasted on warriors and rogues."] = "Les améliorations utiles aux seules classes à mana, comme Intelligence des Arcanes, Sagesse et Esprit divin, sont gâchées sur les guerriers et les voleurs."
L["Hide players known to be out of range"] = "Masquer les joueurs que l'on sait hors de portée"
L["When the game will not tell us the range -- common on this client -- they are still offered."] = "Quand le jeu ne nous indique pas la portée -- fréquent sur ce client -- ils sont quand même proposés."
L["How near a passer-by has to be"] = "Distance maximale des passants"
L["Being in range is not the same as being near. Arcane Intellect and its like reach about thirty yards, which in a city is everybody on the screen."] = "Être à portée n'est pas la même chose qu'être proche. Intelligence des Arcanes et les sorts semblables portent à environ trente mètres, ce qui, en ville, représente tout le monde à l'écran."
L["|cffffd100Anywhere I can cast|r -- about thirty yards, as it was."] = "|cffffd100Partout où je peux lancer|r -- environ trente mètres, comme avant."
L["|cffffd100Nearby|r -- about ten yards."] = "|cffffd100À proximité|r -- environ dix mètres."
L["|cffffd100Right beside me|r -- about five yards."] = "|cffffd100Juste à côté de moi|r -- environ cinq mètres."
L["This only applies to passers-by. Somebody who buffed you was close enough a moment ago, your group is your group, and whoever you have targeted or focused you picked on purpose -- none of them are measured."] = "Ne s'applique qu'aux passants. Quelqu'un qui vous a buffé était assez proche il y a un instant, votre groupe reste votre groupe, et votre cible ou votre focalisation a été choisie exprès -- aucun d'eux n'est mesuré."
L["The game will not say how far away somebody is, so this is measured with whatever this client offers and lands on the nearest step it has. When it cannot measure at all, everybody in casting range is offered, as before."] = "Le jeu ne dit pas à quelle distance se trouve quelqu'un, donc la mesure se fait avec les moyens qu'offre ce client et retombe sur le palier le plus proche dont il dispose. Quand il ne peut rien mesurer du tout, tous ceux à portée de sort sont proposés, comme avant."
L["Only offer passers-by in cities and inns"] = "Ne proposer les passants qu'en ville et dans les auberges"
L["Out in the world, passers-by are left alone; they are offered only where the game shows you as resting, which is in a city or an inn."] = "Dans le reste du monde, les passants sont laissés tranquilles ; ils ne sont proposés que là où le jeu vous indique au repos, c'est-à-dire en ville ou dans une auberge."
L["Somebody who buffed you, your group, and whoever you have targeted or focused are offered anywhere."] = "Ceux qui vous ont buffé, votre groupe et votre cible ou votre focalisation sont proposés partout."
L["If the game will not say whether you are resting, passers-by are offered as usual."] = "Si le jeu ne dit pas si vous êtes au repos, les passants sont proposés comme d'habitude."
L["Drop people who are probably gone"] = "Retirer les joueurs sans doute partis"
L["Somebody who buffed you is rarely your target or showing a nameplate, so there is usually no way to range-check them. What we do know is that they were within casting range the moment they buffed you. With this on, that counts for a short while and then they are let go."] = "Quelqu'un qui vous a buffé est rarement votre cible et a rarement une barre d'info visible, donc il est généralement impossible de vérifier s'il est à portée. Ce que l'on sait, c'est qu'il était à portée de sort au moment où il vous a buffé. Avec cette option activée, cela compte pendant un court moment, puis il est retiré."
L["Let them go after (seconds)"] = "Les retirer après (secondes)"
L["How long after somebody buffs you that counts as proof they were in range. It runs from their buff, not from the moment they walk off: nothing here can see them go."] = "Combien de temps après vous avoir buffé un joueur est encore considéré comme à portée. Le délai court à partir de son amélioration, pas du moment où il s'éloigne : rien ici ne permet de le voir partir."
L["Minimum level"] = "Niveau minimum"
L["Players below this are never offered. The level is read off the unit, so somebody we only know by name -- the usual case for a passer-by who buffed you -- cannot be level-checked at all and is offered anyway."] = "Les joueurs en dessous de ce niveau ne sont jamais proposés. Le niveau se lit sur l'unité : quelqu'un que l'on ne connaît que par son nom -- le cas habituel d'un passant qui vous a buffé -- ne peut donc pas du tout être vérifié, et il est proposé quand même."
L["Never offer"] = "Ne jamais proposer"
L["Nobody is on the list. Shift-right-click the prompt to put whoever it is showing on it, or add a name below."] = "Personne n'est sur la liste. Faites un Maj-clic droit sur le panneau pour ajouter à la liste le joueur affiché, ou ajoutez un nom ci-dessous."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Une personne est sur la liste. Rien ne lui est jamais proposé, ni comme passant ni comme membre de votre groupe."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "%d personnes sont sur la liste. Rien ne leur est jamais proposé, ni comme passants ni comme membres de votre groupe."
L["Somebody on it who buffs you is still offered the favour back: returning a favour is what Manners is for. Shift-right-click them on the prompt to let that favour go."] = "Si quelqu'un de la liste vous buffe, il vous est quand même proposé de lui rendre la politesse : rendre la politesse, c'est à ça que sert Manners. Faites un Maj-clic droit sur le panneau quand il y est affiché pour abandonner cette faveur."
L["Add somebody by name"] = "Ajouter quelqu'un par son nom"
L["Spelled the way the prompt shows them. Capitals do not matter."] = "Orthographié comme sur le panneau. Les majuscules n'ont pas d'importance."
L["On the list"] = "Sur la liste"
L["Take them off"] = "Retirer de la liste"
L["Clear the list"] = "Vider la liste"
L["Take everybody off the never-offer list?"] = "Retirer tout le monde de la liste d'exclusion ?"
L["General"] = "Général"
L["Enable"] = "Activer"
L["Manners is switched off, so the prompt will never appear. Everything below is still saved."] = "Manners est désactivé, donc le panneau n'apparaîtra jamais. Tout ce qui suit reste enregistré."
L["Your class has no buffs it can cast on another player."] = "Votre classe n'a aucune amélioration à lancer sur un autre joueur."
L["Manners has nothing to offer here. It is still worth keeping installed on an alt that does."] = "Manners n'a rien à proposer ici. Cela vaut quand même la peine de le garder installé pour un autre personnage qui, lui, en a."
L["Manners could not work out what you can cast."] = "Manners n'a pas pu déterminer ce que vous pouvez lancer."
L["Either your class has nothing for other players, or the spell probe came back empty -- %s says which."] = "Soit votre classe n'a rien pour les autres joueurs, soit la détection des sorts n'a rien renvoyé -- %s vous dira lequel des deux."
L["How this works"] = "Fonctionnement"
L["Blizzard does not let an addon cast a spell by itself, so this one does everything except the keypress: it works out who deserves a buff and puts them on the prompt. Click the prompt and it casts."] = "Blizzard ne permet pas à un addon de lancer un sort tout seul, donc celui-ci fait tout sauf l'appui sur la touche : il détermine qui mérite une amélioration et l'affiche sur le panneau. Cliquez sur le panneau et le sort est lancé."
L["Putting it on a key"] = "Raccourci"
L["Make the macro below and drag it onto a bar, or bind a key under Options > Keybindings > Manners."] = "Créez la macro ci-dessous et faites-la glisser sur une barre, ou assignez un raccourci dans Options > Raccourcis clavier > Manners."
L["Getting started"] = "Pour commencer"
L["Create the macro"] = "Créer la macro"
L["Adds a macro called Manners containing %s. Drag it onto an action bar and it fires the prompt."] = "Ajoute une macro nommée Manners contenant %s. Faites-la glisser sur une barre d'action et elle active le panneau."
L["Snooze"] = "Pause"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100En pause jusqu'à %s.|r Pendant un combat, le panneau reste tel qu'il était au début du combat, et suit la pause une fois le combat terminé."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged and casts nothing; once you lock it, it stays away until the snooze ends."] = "|cffffd100En pause jusqu'à %s.|r Le panneau est déverrouillé : il reste donc affiché pour que vous puissiez le déplacer, et ne lance rien ; une fois que vous l'aurez verrouillé, il restera masqué jusqu'à la fin de la pause."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100En pause jusqu'à %s.|r Pas de panneau d'ici là, mais les joueurs qui vous buffent sont toujours repérés."
L["Keep the prompt out of the way for a while without switching Manners off. It comes back by itself when the time is up, and a %s ends a snooze as well. One started in a fight takes effect when the fight ends."] = "Mettez le panneau de côté un moment sans désactiver Manners. Il revient tout seul une fois le temps écoulé, et un %s met aussi fin à la pause. Une pause lancée en combat prend effet à la fin du combat."
L["Stop snoozing"] = "Reprendre"
L["Minimap"] = "Minicarte"
L["Show minimap button"] = "Afficher le bouton de la minicarte"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners reste de toute façon dans le menu des addons (sous la minicarte)."
L["Chat"] = "Discussion"
L["Tell me in chat what the addon is doing"] = "M'indiquer dans la discussion ce que fait l'addon"
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Une ligne quand quelqu'un vous buffe, quand une faveur est comptée comme rendue, et quand un clic échoue, est passé, ou laisse une faveur encore due."
L["Only you see any of it; nothing is ever said to anybody else from here. Use it to tell 'the buff was never noticed' apart from 'it was noticed but they could not be reached' -- two very different problems."] = "Vous seul voyez tout cela ; rien n'est jamais dit à qui que ce soit d'autre depuis ici. Servez-vous-en pour distinguer « l'amélioration n'a jamais été repérée » de « elle a été repérée mais le joueur était hors d'atteinte » -- deux problèmes bien différents."
L["Share settings"] = "Partager les paramètres"
L["Copy these settings as one line of text, to keep or to give to somebody, or paste one you were given. Whether Manners is on, whether the prompt is locked, where it sits, the click log and the minimap button stay as they are. A pasted line never switches on speaking when you buff, and while you have it on, what you say and where stays yours too."] = "Copiez ces paramètres sous forme d'une ligne de texte, pour les garder ou les donner à quelqu'un, ou collez-en une que l'on vous a donnée. L'activation de Manners, le verrouillage du panneau, sa position, le journal des clics et le bouton de la minicarte restent tels quels. Une ligne collée n'active jamais les messages en discussion quand vous buffez, et si vous les avez activés, vos phrases et votre canal sont conservés aussi."
L["Hide the text"] = "Masquer le texte"
L["Show my settings as text"] = "Afficher mes paramètres en texte"
L["Shows these settings as one line of text in a box below, ready to select and copy. %s opens it too."] = "Affiche ces paramètres sous forme d'une ligne de texte dans un champ ci-dessous, prête à être sélectionnée et copiée. %s l'ouvre aussi."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Cliquez dans le champ, appuyez sur Ctrl+A pour tout sélectionner, puis sur Ctrl+C pour copier (Cmd sur Mac)."
L["Paste settings to use them"] = "Coller des paramètres pour les utiliser"
L["Replaces the settings on this profile with the ones in the text. %s puts yours back."] = "Remplace les paramètres de ce profil par ceux du texte. %s rétablit les vôtres."
L["Open the ledger"] = "Ouvrir le registre"
L["A window listing who buffed you and with what, whether you returned it, and who you buffed without being asked. Also %s, or shift-click the minimap button."] = "Une fenêtre qui liste qui vous a buffé et avec quoi, si vous avez rendu la politesse, et qui vous avez buffé spontanément. Accessible aussi par %s, ou d'un Maj-clic sur le bouton de la minicarte."
L["Already buffed"] = "Déjà buffé"
L["If they already have the buff"] = "S'il a déjà l'amélioration"
L["Reading whether somebody has a buff needs the game's permission. See the Diagnostics tab for which of your buffs qualify."] = "Savoir si quelqu'un a une amélioration nécessite l'autorisation du jeu. Consultez l'onglet Diagnostic pour voir lesquelles de vos améliorations sont concernées."
L["Somebody who buffed you is offered the favour back whichever you choose, even if they already have it."] = "Quel que soit votre choix, quelqu'un qui vous a buffé est proposé pour que vous lui rendiez la politesse, même s'il a déjà l'amélioration."
L["Leave them alone (unless they buffed you)"] = "Ne rien proposer (sauf s'il vous a buffé)"
L["Offer a top-up when it is running out"] = "Proposer un rafraîchissement quand elle s'épuise"
L["Always offer, whatever they have"] = "Toujours proposer, quoi qu'il ait"
L["Top up when under (minutes) are left"] = "Rafraîchir quand il reste moins de (minutes)"
L["Only offer a refresh once their remaining time drops below this. Somebody whose buff timer cannot be read is left alone -- unless they buffed you, in which case they are offered the favour back anyway."] = "Ne propose un rafraîchissement qu'une fois la durée restante passée sous ce seuil. Quelqu'un dont la durée d'amélioration ne peut pas être lue est laissé tranquille -- sauf s'il vous a buffé, auquel cas il est proposé quand même pour que vous lui rendiez la politesse."
L["Everyone nearby will be offered constantly, including people whose buff has barely ticked down. Expect to be spending mana."] = "Tous les joueurs proches seront proposés en permanence, y compris ceux dont l'amélioration a à peine commencé à s'écouler. Attendez-vous à dépenser du mana."
L["Nothing is read in this mode, so |cffffd100Whoever I have targeted comes first|r has nothing to go on: your target is ranked by why they are on the list like anybody else."] = "Rien n'est lu dans ce mode, donc |cffffd100Ma cible passe en premier|r n'a rien sur quoi s'appuyer : votre cible est classée selon la raison de sa présence dans la liste, comme n'importe qui."
L["Timing"] = "Délais"
L["Remember a buff for (seconds)"] = "Mémoriser une amélioration pendant (secondes)"
L["How long a favour is remembered. Somebody the game can still see stays on the prompt this long. Somebody it cannot see is let go sooner if |cffffd100Let them go after|r is shorter, while |cffffd100Drop people who are probably gone|r is on, under Who to buff."] = "Durée pendant laquelle une faveur est mémorisée. Quelqu'un que le jeu voit encore reste sur le panneau pendant tout ce temps. Quelqu'un qu'il ne voit pas est retiré plus tôt si |cffffd100Les retirer après|r est plus court, tant que |cffffd100Retirer les joueurs sans doute partis|r est activé, dans l'onglet Qui buffer."
L["Remember them across a reload"] = "Les mémoriser après un rechargement"
L["A favour noticed a minute before a disconnect is the case this is for. The clock keeps running while you are away, so somebody whose time ran out in the meantime is not brought back."] = "C'est pour le cas d'une faveur repérée une minute avant une déconnexion. Le temps continue de s'écouler pendant votre absence, donc quelqu'un dont le délai a expiré entre-temps ne revient pas."
L["Stored against this character, never shared between profiles. Switching it off deletes what has already been stored."] = "Enregistré pour ce personnage, jamais partagé entre profils. Désactiver l'option efface ce qui a déjà été enregistré."
L["Wait before offering the same spell again (seconds)"] = "Attendre avant de reproposer le même sort (secondes)"
L["After you click, how long before that spell is offered to that player again. Covers casts that failed out of sight."] = "Après votre clic, délai avant que ce sort soit de nouveau proposé à ce joueur. Couvre les sorts lancés qui ont échoué hors de votre vue."
L["Per spell, not per person: cast Fortitude and the next scan can still offer them Divine Spirit, which is how the walk down your buffs works at all. Right-click the prompt to skip somebody and the same number applies to the whole person -- nothing is offered to them until it lifts."] = "Par sort, pas par personne : lancez Robustesse et l'analyse suivante peut encore lui proposer Esprit divin, et c'est justement ainsi que fonctionne le parcours de vos améliorations. Faites un clic droit sur le panneau pour passer quelqu'un et le même délai s'applique à la personne tout entière -- rien ne lui est proposé tant qu'il n'est pas écoulé."
L["Scan every (seconds)"] = "Analyser toutes les (secondes)"
L["Lower is more responsive and slightly heavier."] = "Plus la valeur est basse, plus c'est réactif, mais un peu plus lourd."
L["Out of the way"] = "Masquage"
L["Keep the prompt away while you are on a mount, since casting would take you off it. It comes back when you get off, if there is somebody to buff."] = "Masque le panneau tant que vous êtes sur une monture, puisque lancer un sort vous en ferait descendre. Il revient quand vous descendez de monture, s'il y a quelqu'un à buffer."
L["It already stays away while you are dead, on a flight path or in a vehicle, where nothing can be cast. In a fight the prompt stays as the fight found it, and follows this once the fight ends."] = "Il est déjà masqué quand vous êtes mort, en trajet aérien ou dans un véhicule, où rien ne peut être lancé. Pendant un combat, le panneau reste tel qu'il était au début du combat, et suit ce réglage une fois le combat terminé."
L["When you click"] = "Au clic"
L["|cffffd100In combat.|r Blizzard freezes the macro on the prompt for the length of a fight, so these settings apply once it ends. Until then a press runs the macro already on the button."] = "|cffffd100En combat.|r Blizzard fige la macro du panneau pendant toute la durée d'un combat, donc ces paramètres s'appliquent une fois celui-ci terminé. D'ici là, un appui lance la macro déjà présente sur le bouton."
L["Targeting"] = "Ciblage"
L["Hand my target back afterwards"] = "Rétablir ma cible ensuite"
L["Buffing somebody means targeting them first -- a named conditional only reaches your own party or raid, and this prompt is mostly for passers-by. With this on, your previous target is restored immediately after the cast."] = "Buffer quelqu'un implique de le cibler d'abord -- une condition de macro qui vise un nom n'atteint que votre propre groupe ou raid, et ce panneau sert surtout aux passants. Avec cette option activée, votre cible précédente est rétablie juste après le sort."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Tout ce que vous pouvez proposer se lance sur vous et est entendu par votre groupe, donc le panneau ne prend jamais votre cible et n'a aucune cible à rétablir."
L["The prompt runs |cffffd100%s|r, then the cast, then |cffffd100%s|r -- except, outside a fight, for somebody who is already your target, who stays targeted. A conditional -- %s -- resolves only for somebody already in your party or raid, and this prompt is mostly for passers-by, so the macro takes your target rather than aiming past it."] = "Le panneau exécute |cffffd100%s|r, puis le sort, puis |cffffd100%s|r -- sauf, hors combat, pour quelqu'un qui est déjà votre cible, qui reste ciblé. Une condition de macro -- %s -- ne fonctionne que pour quelqu'un déjà dans votre groupe ou raid, et ce panneau sert surtout aux passants, donc la macro change votre cible plutôt que de la contourner."
L["The prompt runs |cffffd100%s|r, then the cast, and leaves them targeted. A conditional -- %s -- resolves only for somebody already in your party or raid, and this prompt is mostly for passers-by, so the macro takes your target rather than aiming past it."] = "Le panneau exécute |cffffd100%s|r, puis le sort, et laisse le joueur ciblé. Une condition de macro -- %s -- ne fonctionne que pour quelqu'un déjà dans votre groupe ou raid, et ce panneau sert surtout aux passants, donc la macro change votre cible plutôt que de la contourner."
L["Speech"] = "Messages"
L["Say something when you buff somebody. The line is added to the macro the prompt runs, so it goes out as you talking rather than as an addon."] = "Dites quelque chose quand vous buffez quelqu'un. La ligne est ajoutée à la macro exécutée par le panneau, donc elle part comme si c'était vous qui parliez, et non un addon."
L["This matters: the game refuses addon-sent %s and %s outside instances, which is exactly where somebody buffs you in passing. Going through the macro sidesteps that."] = "C'est important : le jeu refuse les messages %s et %s envoyés par un addon hors des instances, c'est-à-dire justement là où l'on vous buffe en passant. Passer par la macro contourne ce blocage."
L["Say something"] = "Dire quelque chose"
L["Channel"] = "Canal"
L["Say"] = "Dire"
L["Yell"] = "Crier"
L["Party"] = "Groupe"
L["Raid"] = "Raid"
L["Emote"] = "Emote"
L["Only when returning a favour"] = "Seulement pour rendre la politesse"
L["Speak only when buffing somebody who buffed you first. Leave this on unless you want to announce every stranger you buff."] = "Ne parler que lorsque vous buffez quelqu'un qui vous a buffé en premier. Laissez cette option activée sauf si vous voulez annoncer chaque inconnu que vous buffez."
L["Phrases"] = "Phrases"
L["Load a set"] = "Charger une série"
L["Replaces the lines below. Edit them afterwards as much as you like."] = "Remplace les lignes ci-dessous. Modifiez-les ensuite autant que vous voulez."
L["Replace everything in the box below with the %s lines?"] = "Remplacer tout le contenu du champ ci-dessous par la série « %s » ?"
L["loaded the %s lines."] = "série « %s » chargée."
L["One per line -- a random one is picked each time the prompt changes target. Tokens: |cff888888{name}|r the player, |cff888888{buff}|r the spell."] = "Une par ligne -- une phrase est tirée au hasard chaque fois que le panneau change de joueur. Balises : |cff888888{name}|r le joueur, |cff888888{buff}|r le sort."
L["The whole macro cannot exceed 255 characters, so how long a line may be depends on the name and on whether your target is handed back. One that will not fit is dropped rather than cut off -- |cffffd100Roll a few|r shows what would really go out. An empty box goes back to the chosen set -- switch off |cffffd100Say something|r to stay quiet."] = "La macro entière ne peut pas dépasser 255 caractères, donc la longueur possible d'une ligne dépend du nom et du rétablissement ou non de votre cible. Une ligne trop longue est écartée plutôt que coupée -- |cffffd100Tirer quelques lignes|r montre ce qui partirait vraiment. Un champ vide revient à la série choisie -- désactivez |cffffd100Dire quelque chose|r pour rester silencieux."
L["Roll a few"] = "Tirer quelques lignes"
L["Somebody"] = "Quelqu'un"
L["(nothing -- speech off, or no usable lines)"] = "(rien -- messages désactivés, ou aucune ligne utilisable)"
L["A macro cannot exceed 255 characters, so an over-long line is dropped rather than truncated. The message goes out when you click, so it is sent even if the cast then fails out of range or line of sight."] = "Une macro ne peut pas dépasser 255 caractères, donc une ligne trop longue est écartée plutôt que tronquée. Le message part au moment du clic, donc il est envoyé même si le sort échoue ensuite, hors de portée ou hors du champ de vision."
L["Prompt"] = "Panneau"
L["|cffffd100In combat.|r Blizzard freezes secure frames, so the prompt cannot be restyled or re-aimed until the fight ends. Anything you change here is saved and appears the moment you leave combat."] = "|cffffd100En combat.|r Blizzard fige les cadres sécurisés, donc l'apparence et la cible du panneau ne peuvent pas changer avant la fin du combat. Tout ce que vous modifiez ici est enregistré et s'applique dès que vous sortez du combat."
L["Stop preview"] = "Arrêter l'aperçu"
L["Preview"] = "Aperçu"
L["Show a sample entry so you can style the prompt without waiting for one. It stays for as long as this window is open; once you close it, twenty seconds more, or until somebody real turns up."] = "Affiche une entrée d'exemple pour régler l'apparence du panneau sans attendre qu'un vrai joueur apparaisse. Elle reste tant que cette fenêtre est ouverte ; une fois la fenêtre fermée, encore vingt secondes, ou jusqu'à ce qu'un vrai joueur se présente."
L["Locked"] = "Verrouillé"
L["Unlock to drag the prompt. It will not cast while unlocked."] = "Déverrouillez pour faire glisser le panneau. Il ne lance rien tant qu'il est déverrouillé."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "déverrouillé, mais l'addon est |cffff8080désactivé|r, donc il n'y a aucun panneau à faire glisser -- activez-le d'abord."
L["Reset position"] = "Réinitialiser la position"
L["Style"] = "Style"
L["Where the reason colour goes"] = "Emplacement de la couleur de raison"
L["A ring around the icon reads better than a stripe at the panel edge, which ends up competing with the icon rather than framing it."] = "Un anneau autour de l'icône se lit mieux qu'une bande au bord du panneau, qui finit par concurrencer l'icône au lieu de l'encadrer."
L["The framed look has no stripe at all -- it would run down the inside of its border -- so on it the stripe settings do nothing."] = "L'apparence Encadré n'a pas de bande du tout -- elle longerait l'intérieur de sa bordure -- donc les réglages de bande n'y ont aucun effet."
L["Ring around the icon"] = "Anneau autour de l'icône"
L["Stripe down the left edge"] = "Bande sur le bord gauche"
L["Both"] = "Les deux"
L["Neither"] = "Aucun des deux"
L["Colour it by reason"] = "Colorer selon la raison"
L["Pale blue for somebody you targeted yourself, amber when returning a favour, deeper blue for your group, grey for passers-by. That is also the order they are offered in."] = "Bleu pâle pour un joueur que vous avez ciblé vous-même, ambre pour rendre la politesse, bleu plus soutenu pour votre groupe, gris pour les passants. C'est aussi l'ordre dans lequel ils sont proposés."
L["The first of those only ever appears while |cffffd100Whoever I have targeted comes first|r is on, under Who to buff, and never while |cffffd100If they already have the buff|r is set to Always offer, under When."] = "La première de ces couleurs n'apparaît que si l'option |cffffd100Ma cible passe en premier|r est activée, dans l'onglet Qui buffer, et jamais quand |cffffd100S'il a déjà l'amélioration|r est réglé sur « Toujours proposer », dans l'onglet Quand."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "Il ne reste rien à colorer : l'anneau est dessiné derrière l'icône, qui est désactivée, et l'apparence Encadré n'a pas de bande."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "Il ne reste rien à colorer : arrondir l'icône remplace l'anneau par un masque, et l'apparence Encadré n'a pas de bande."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "Il ne reste rien à colorer : l'anneau est dessiné derrière l'icône, qui est désactivée."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "Il ne reste rien à colorer : arrondir l'icône remplace l'anneau par un masque."
L["There is nothing left to colour: the framed look has no stripe."] = "Il ne reste rien à colorer : l'apparence Encadré n'a pas de bande."
L["Accent colour"] = "Couleur d'accent"
L["Used for the ring, the stripe, or both -- whichever the setting above asks for."] = "Utilisée pour l'anneau, la bande ou les deux -- selon ce que demande le réglage ci-dessus."
L["Look"] = "Apparence"
L["Glass -- dark panel, soft shadow"] = "Verre -- fond sombre, ombre douce"
L["Framed -- flat panel, thin border"] = "Encadré -- fond uni, bordure fine"
L["Minimal -- text only, no panel"] = "Minimal -- texte seul, sans fond"
L["Panel colour"] = "Couleur du fond"
L["Getting your attention"] = "Attirer votre attention"
L["When someone buffs you"] = "Quand quelqu'un vous buffe"
L["Pulse keeps breathing until you have returned the favour or they are gone. Flash once is easy to miss if you were looking elsewhere."] = "« Pulser jusqu'à traitement » continue de battre jusqu'à ce que vous ayez rendu la politesse ou que le joueur soit parti. « Clignoter une fois » passe facilement inaperçu si vous regardiez ailleurs."
L["It lights up round the spell icon and sweeps the stripe, and with Effects on Full the panel catches the light the moment they buff you. With the icon hidden, no stripe showing and no light either -- Effects on Calm, or the Minimal look, which has no panel -- there is nothing for it to do."] = "La lueur entoure l'icône du sort et balaie la bande, et avec Effets sur Complet, le panneau capte la lumière dès que le joueur vous buffe. Si l'icône est masquée, qu'aucune bande n'est visible et qu'il n'y a pas de lumière non plus -- Effets sur Calme, ou l'apparence Minimal, qui n'a pas de fond -- ce réglage n'a alors aucun effet."
L["Pulse until dealt with"] = "Pulser jusqu'à traitement"
L["Flash once"] = "Clignoter une fois"
L["Nothing"] = "Rien"
L["Effects"] = "Effets"
L["Full: when a buff lands, light crosses the panel and a ring pops out of the spell icon, if it is shown; a refused buff makes the text give a small shake; somebody who buffs you makes the panel catch the light, unless the setting above is Nothing; and after your last buff the prompt fades out instead of vanishing."] = "Complet : quand une amélioration réussit, une lumière traverse le panneau et un anneau jaillit de l'icône du sort, si elle est affichée ; une amélioration refusée fait légèrement trembler le texte ; quand quelqu'un vous buffe, le panneau capte la lumière, sauf si le réglage ci-dessus est sur « Rien » ; et après votre dernière amélioration, le panneau s'estompe au lieu de disparaître d'un coup."
L["Calm: none of that movement. The prompt still fades in, and the glow set above still works."] = "Calme : aucun de ces mouvements. Le panneau apparaît toujours en fondu, et la lueur réglée ci-dessus fonctionne toujours."
L["The Minimal look has no panel, so no light crosses it. The cooldown sweep on the icon has its own switch, under Icon and queue. In a fight, Stay quiet in combat keeps the outcome still as well."] = "L'apparence Minimal n'a pas de fond, donc aucune lumière ne le traverse. Le balayage du temps de recharge sur l'icône a sa propre option, dans la section Icône et file d'attente. En combat, « Rester discret en combat » supprime aussi l'animation du résultat."
L["Full"] = "Complet"
L["Calm -- less movement"] = "Calme -- moins de mouvement"
L["Play a sound"] = "Jouer un son"
L["Play a sound when somebody new reaches the top of the queue."] = "Joue un son quand une nouvelle personne arrive en tête de la file d'attente."
L["Sound"] = "Son"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(non chargé)|r"
L["Only when somebody buffed me"] = "Seulement si quelqu'un m'a buffé"
L["Off, every new person on the prompt makes a noise -- including strangers you happen to walk past."] = "Si cette option est désactivée, chaque nouvelle personne sur le panneau déclenche un son -- y compris les inconnus que vous croisez par hasard."
L["%s is silent. Pick a sound above."] = "%s est silencieux. Choisissez un son ci-dessus."
L["Position and size"] = "Position et taille"
L["Put it"] = "Emplacement"
L["Three places that are already right. Dragging the prompt afterwards leaves this blank, because it is then not on one of them."] = "Trois emplacements tout prêts. Si vous faites ensuite glisser le panneau, ce champ reste vide, puisqu'il n'est alors plus sur l'un d'eux."
L["X offset"] = "Décalage X"
L["Y offset"] = "Décalage Y"
L["Width"] = "Largeur"
L["Height"] = "Hauteur"
L["Scale"] = "Échelle"
L["Opacity"] = "Opacité"
L["Stay quiet in combat"] = "Rester discret en combat"
L["A click still casts in combat, and the prompt still flashes to say what happened -- red if it failed. With this on it does not -- the panel simply sits there dimmed for the length of the fight, with no cooldown sweep on the icon."] = "En combat, un clic lance toujours le sort, et le panneau clignote toujours pour indiquer le résultat -- en rouge en cas d'échec. Avec cette option activée, il ne clignote pas -- le panneau reste simplement là, grisé, pendant tout le combat, sans balayage du temps de recharge sur l'icône."
L["It stays on screen in a fight on purpose: your key binding would still cast the frozen macro if it were hidden."] = "Il reste à l'écran en combat exprès : même masqué, votre raccourci lancerait toujours la macro figée."
L["Text"] = "Texte"
L["First line"] = "Première ligne"
L["Tokens: {name} {reason} {count} {class} {buff} {time}"] = "Balises : {name} {reason} {count} {class} {buff} {time}"
L["Show a second line"] = "Afficher une deuxième ligne"
L["Needs a prompt at least %d pixels tall at this font size."] = "Il faut un panneau d'au moins %d pixels de haut avec cette taille de police."
L["|cff888888{name}|r who   |cff888888{reason}|r why   |cff888888{count}|r how many more   |cff888888{class}|r their class   |cff888888{buff}|r the spell"] = "|cff888888{name}|r qui   |cff888888{reason}|r pourquoi   |cff888888{count}|r combien d'autres   |cff888888{class}|r sa classe   |cff888888{buff}|r le sort"
L["|cff888888{time}|r what theirs has left, on a top-up and nowhere else"] = "|cff888888{time}|r le temps restant sur la sienne, pour un rafraîchissement uniquement"
L["The second line always shows the reason."] = "La deuxième ligne affiche toujours la raison."
L["Wording: your target"] = "Texte : votre cible"
L["Somebody you targeted yourself outranks everyone else, including a favour owed -- but only when the game lets us see they are missing it, and only while that is switched on under Who to buff."] = "Un joueur que vous avez ciblé vous-même passe avant tous les autres, même une faveur due -- mais seulement quand le jeu nous laisse voir qu'il n'a pas l'amélioration, et seulement si cette option est activée dans l'onglet Qui buffer."
L["Wording: buffed you"] = "Texte : vous a buffé"
L["Wording: in your group"] = "Texte : dans votre groupe"
L["Wording: nearby"] = "Texte : à proximité"
L["Wording: topping one up"] = "Texte : rafraîchissement"
L["Used instead of the four above when they already have the buff and it is about to run out, which only the refresh mode offers. |cffffd100{time}|r is how long theirs has left."] = "Remplace les quatre textes ci-dessus quand le joueur a déjà l'amélioration et qu'elle va bientôt s'épuiser, ce que seul le mode rafraîchissement propose. |cffffd100{time}|r est le temps qu'il reste sur la sienne."
L["Wording: state unknown"] = "Texte : état inconnu"
L["Used when the game will not let addons read whether they already have it."] = "Utilisé quand le jeu ne laisse pas les addons savoir si le joueur l'a déjà."
L["Font"] = "Police"
L["Font size"] = "Taille de police"
L["Text colour"] = "Couleur du texte"
L["Colour names by class"] = "Colorer les noms selon la classe"
L["Icon and queue"] = "Icône et file d'attente"
L["Show spell icon"] = "Afficher l'icône du sort"
L["Icon size"] = "Taille de l'icône"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "L'icône reste dans le panneau -- rendez-le d'abord plus haut ou plus large pour l'agrandir."
L["The icon is held at %d to fit a prompt %d wide."] = "L'icône est limitée à %d pour tenir dans un panneau de %d de large."
L["The icon is held at %d to fit a prompt %d high."] = "L'icône est limitée à %d pour tenir dans un panneau de %d de haut."
L["Round the icon off"] = "Arrondir l'icône"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Découpe l'icône en cercle. Cela ressemble plus à un portrait qu'à un sort, donc c'est désactivé par défaut."
L["The mask goes where the ring was, so a rounded icon has no ring to colour -- move the reason colour to the stripe if you want both. The glow when somebody buffs you follows the circle."] = "Le masque prend la place de l'anneau, donc une icône arrondie n'a pas d'anneau à colorer -- mettez la couleur de raison sur la bande si vous voulez les deux. La lueur quand quelqu'un vous buffe suit le cercle."
L["Show the global cooldown on the icon"] = "Afficher le temps de recharge global sur l'icône"
L["Sweeps the spell icon while the global cooldown runs after a cast, the way your action bars do, so you can see when the next press will go through."] = "Balaie l'icône du sort pendant le temps de recharge global après un sort lancé, comme le font vos barres d'action, pour que vous voyiez quand le prochain appui passera."
L["Not in a fight while Stay quiet in combat is on."] = "Pas en combat quand l'option « Rester discret en combat » est activée."
L["Show how many are waiting"] = "Afficher le nombre de joueurs en attente"
L["List the next few below"] = "Lister les suivants en dessous"
L["How many to list"] = "Nombre de suivants à lister"
L["Diagnostics"] = "Diagnostic"
L["Log every click to chat"] = "Afficher chaque clic dans la discussion"
L["Prints what the button was actually holding at the moment you clicked it, and what the game did with it. Noisy; for working out why a cast did not happen."] = "Affiche ce que le bouton contenait vraiment au moment du clic, et ce que le jeu en a fait. Bavard ; sert à comprendre pourquoi un sort n'est pas parti."
L["What this client allows"] = "Ce que ce client autorise"
L["Class: |cffffffff%s|r"] = "Classe : |cffffffff%s|r"
L["learned: |cff00ff00yes|r"] = "appris : |cff00ff00oui|r"
L["learned: |cff808080no|r"] = "appris : |cff808080non|r"
L["missing-check: |cff00ff00works|r"] = "détection d'absence : |cff00ff00fonctionne|r"
L["missing-check: |cffff8080blocked|r"] = "détection d'absence : |cffff8080bloquée|r"
L["this client has never heard of spell %s, so Manners will never offer this one. That is a mistake in Manners -- please report it."] = "ce client n'a jamais entendu parler du sort %s, donc Manners ne proposera jamais celui-ci. C'est une erreur de Manners -- merci de la signaler."
L["this client doesn't know spell %s, so Manners can't see that version on anyone -- somebody already carrying it may be offered this anyway. That is a mistake in Manners -- please report it."] = "ce client ne connaît pas le sort %s, donc Manners ne peut voir cette version sur personne -- quelqu'un qui l'a déjà peut quand même être proposé. C'est une erreur de Manners -- merci de la signaler."
L["Where the missing-check is blocked, the game will not let addons read that aura. Players are still offered, but some may already have the buff."] = "Là où la détection d'absence est bloquée, le jeu ne laisse pas les addons lire cette aura. Les joueurs sont toujours proposés, mais certains ont peut-être déjà l'amélioration."
L["Nothing to report: this character has no buffs it can put on another player."] = "Rien à signaler : ce personnage n'a aucune amélioration à lancer sur un autre joueur."
L["What has broken"] = "Erreurs rencontrées"
L["(%d in all this session, %d kept -- |cffffd100%s|r)"] = "(%d au total pendant cette session, %d conservées -- |cffffd100%s|r)"
L["(%d in all this session -- |cffffd100%s|r)"] = "(%d au total pendant cette session -- |cffffd100%s|r)"
L["Nothing has broken this session."] = "Aucune erreur pendant cette session."
L["Reporting a bug"] = "Signaler un bug"
L["Hide the report"] = "Masquer le rapport"
L["Copy for a bug report"] = "Copier pour un rapport de bug"
L["Opens a box with the build number, what this client allows, the settings that change what it does and anything that has broken -- ready to select and paste."] = "Ouvre une zone avec le numéro de version, ce que ce client autorise, les paramètres qui changent son comportement et les erreurs rencontrées -- le tout prêt à être sélectionné et collé."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "Désactivé -- le panneau que ce combat a figé reste affiché jusqu'à la fin du combat, et un appui lance toujours son sort."
L["Switched off -- no prompt will appear."] = "Désactivé -- aucun panneau n'apparaîtra."
L["Unlocked, but in this fight the prompt stays as the fight found it, and a press still casts it; it can be dragged once the fight ends."] = "Déverrouillé, mais pendant ce combat, le panneau reste tel qu'il était au début du combat, et un appui lance toujours son sort ; vous pourrez le déplacer une fois le combat terminé."
L["Unlocked -- the prompt this fight froze stays up until it ends, and a press still casts it; then it can be dragged."] = "Déverrouillé -- le panneau que ce combat a figé reste affiché jusqu'à la fin du combat, et un appui lance toujours son sort ; vous pourrez ensuite le déplacer."
L["Unlocked, and snoozed until %s -- the prompt stays up to be dragged and casts nothing; once you lock it, it stays away until the snooze ends."] = "Déverrouillé, et en pause jusqu'à %s -- le panneau reste affiché pour que vous puissiez le déplacer, et ne lance rien ; une fois que vous l'aurez verrouillé, il restera masqué jusqu'à la fin de la pause."
L["Unlocked -- the prompt is up to be dragged and casts nothing until you lock it (%s)."] = "Déverrouillé -- le panneau est affiché pour que vous puissiez le déplacer, et ne lance rien tant que vous ne l'avez pas verrouillé (%s)."
L["Snoozed until %s -- in this fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "En pause jusqu'à %s -- pendant ce combat, le panneau reste tel qu'il était au début du combat, et suit la pause une fois le combat terminé."
L["Snoozed until %s, %s from now -- no prompt until then."] = "En pause jusqu'à %s, dans %s -- aucun panneau d'ici là."
L["Nothing to do: %s"] = "Rien à faire : %s"
