L["Nothing will be offered: %s."] = "Rien ne sera proposé : %s."
L["Nothing learned to cast yet."] = "Aucun sort appris à lancer pour l'instant."
L["Kept away while you are mounted -- %s, on the %s tab."] = "Masqué tant que vous êtes sur une monture -- « %s », dans l'onglet %s."
L["Watching for people to buff."] = "À l'affût de joueurs à buffer."
